mapper.select:
select count(*)
from dev_device_info m
inner join dev_meter_warning_record mw on m.device_id = mw.device_id

    and m.deleted=0
    and m.park_org_id=#{parkOrgId}

        and mw.warning_time >= #{startTime}


        and mw.warning_time <= #{endTime}


        and mw.status = #{status}

select m.`park_org_id`, m.`device_type`, m.`device_name`, mw.id, mw.device_id, mw.warning_code, mw.warning_level, mw.warning_time from dev_device_info m inner join dev_meter_warning_record mw on m.device_id=mw.device_id
and m.deleted=0
and m.park_org_id=#{q.parkOrgId}
and m.device_name like concat('%',#{q.deviceName},'%')
and mw.warning_code=#{q.warningCode}
and mw.warning_time >= #{q.warningTimeStart} and mw.warning_time <= #{q.warningTimeEnd}
and m.park_org_id in
#{parkOrgId}
and mw.device_type=#{q.deviceType}
order by mw.warning_time desc
